## 标准答案

**完整代码：**

```c
#include <stdio.h>
#include <stdbool.h>

/**
 * 判断一个正整数是否为素数
 * 采用试除法优化至 O(√n)
 * @param n 待判断的正整数
 * @return 是素数返回 true，否则返回 false
 */
bool isPrime(int n) {
    // 小于等于1的数不是素数
    if (n <= 1) {
        return false;
    }
    // 2是最小的素数
    if (n == 2) {
        return true;
    }
    // 排除所有大于2的偶数
    if (n % 2 == 0) {
        return false;
    }
    // 从3开始，步长为2，只需检查到 √n
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

/**
 * 将正整数的各位数字顺序颠倒
 * @param n 待处理的正整数
 * @return 逆序后的整数
 */
int reverseNumber(int n) {
    int reversed = 0;
    while (n > 0) {
        // 取出末位数字并追加到结果末尾
        reversed = reversed * 10 + n % 10;
        // 移除已处理的末位
        n /= 10;
    }
    return reversed;
}

int main() {
    int number;

    // 读取用户输入
    if (scanf("%d", &number) != 1) {
        return 0;
    }

    // 根据题目约束，输入必须为正整数
    if (number <= 0) {
        printf("no\n");
        return 0;
    }

    // 可逆素数定义：原数为素数 且 其逆序也为素数
    if (isPrime(number) && isPrime(reverseNumber(number))) {
        printf("yes\n");
    } else {
        printf("no\n");
    }

    return 0;
}
```

**复杂度分析：**

- **时间复杂度：** $O(\sqrt{N})$，其中 $N$ 为输入的整数值。  
  主要开销在于素数判定过程，采用试除法仅需遍历到 $\sqrt{N}$。数字逆序操作的时间复杂度为 $O(\log_{10}N)$（遍历每位数字），相比素数判定可忽略不计。

- **空间复杂度：** $O(1)$，仅使用固定数量的整型变量和布尔标志，与输入数值大小无关，为常数级额外空间。

