// 功能：将正整数的各位数字顺序颠倒，例如123变为321
// 参数：n - 待处理的正整数
// 返回值：逆序后的整数

function reverseNumber(n):
    // 初始化结果为0，用于存储反转后的数字
    reversed ← 0

    // 循环直到处理完所有数字（当n减至0时停止）
    while n > 0 do
        // 取出末位数字（通过取模运算）并追加到结果末尾（乘以10后相加）
        reversed ← reversed × 10 + (n mod 10)
        // 移除已处理的末位数字（整除10）
        n ← n ÷ 10
    end while

    return reversed
end function
