## 标准答案

**完整代码：**
```c
#include <stdio.h>

/*
 * 题目要求：
 * 给定两个矩形的任意一组对角点坐标，求它们相交部分的面积。
 *
 * 思路：
 * 1. 先分别求出每个矩形在 x 轴、y 轴上的左右边界和上下边界。
 * 2. 两矩形在 x 轴上的重叠长度：
 *      min(A的右边界, B的右边界) - max(A的左边界, B的左边界)
 *    若结果 <= 0，则说明在 x 轴上没有有效重叠。
 * 3. y 轴同理。
 * 4. 面积 = x方向重叠长度 * y方向重叠长度
 *    若任一方向重叠长度 <= 0，则面积为 0。
 */

/* 返回两个整数中的较小值 */
int min_int(int a, int b) {
    return (a < b) ? a : b;
}

/* 返回两个整数中的较大值 */
int max_int(int a, int b) {
    return (a > b) ? a : b;
}

int main(void) {
    int Ax1, Ay1, Ax2, Ay2;
    int Bx1, By1, Bx2, By2;

    /* 读取两个矩形的对角点坐标 */
    if (scanf("%d %d %d %d", &Ax1, &Ay1, &Ax2, &Ay2) != 4) {
        return 0;
    }
    if (scanf("%d %d %d %d", &Bx1, &By1, &Bx2, &By2) != 4) {
        return 0;
    }

    /* 规范化矩形A的边界 */
    int A_left   = min_int(Ax1, Ax2);
    int A_right  = max_int(Ax1, Ax2);
    int A_bottom = min_int(Ay1, Ay2);
    int A_top    = max_int(Ay1, Ay2);

    /* 规范化矩形B的边界 */
    int B_left   = min_int(Bx1, Bx2);
    int B_right  = max_int(Bx1, Bx2);
    int B_bottom = min_int(By1, By2);
    int B_top    = max_int(By1, By2);

    /* 计算 x 方向和 y 方向的重叠长度 */
    int overlap_width = min_int(A_right, B_right) - max_int(A_left, B_left);
    int overlap_height = min_int(A_top, B_top) - max_int(A_bottom, B_bottom);

    /* 若不相交或仅边/点接触，则面积为 0 */
    if (overlap_width <= 0 || overlap_height <= 0) {
        printf("0\n");
    } else {
        printf("%d\n", overlap_width * overlap_height);
    }

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：O(1)，只进行了常数次比较与运算
- 空间复杂度：O(1)，只使用了若干整型变量

