                return 1;
            }
            A = tmp;
        }
        A[sizeA++] = x;
    }

    /* 读入集合 B，直到遇到 -1 */
    while (scanf("%d", &x) == 1 && x != -1) {
        if (sizeB == capB) {
            capB = (capB == 0) ? 10 : capB * 2;
            int *tmp = (int *)realloc(B, capB * sizeof(int));
            if (tmp == NULL) {
                free(A);
                free(B);
                return 1;
            }
            B = tmp;
        }
        B[sizeB++] = x;
    }

    /* 计算并输出 A - B */
    int first = 1;  // 用于控制空格输出，避免行末多余空格
    for (int i = 0; i < sizeA; i++) {
        int found = 0;
        for (int j = 0; j < sizeB; j++) {
            if (A[i] == B[j]) {
                found = 1;
                break;
            }
        }
        if (!found) {
            if (!first) {
                printf(" ");
            }
            printf("%d", A[i]);
            first = 0;
        }
    }

    free(A);
    free(B);
    return 0;
}
