**完整代码：**
```c
#include <stdio.h>

#define MAXN 10

int main(void) {
    int n;
    int result[MAXN][MAXN];
    int temp[MAXN][MAXN];
    char op;
    int i, j;

    /* 读取矩阵阶数 */
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    /* 读取第一个矩阵，作为初始结果矩阵 */
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (scanf("%d", &result[i][j]) != 1) {
                return 0;
            }
        }
    }

    /* 依次读取运算符和后续矩阵，直到遇到 # 结束 */
    while (scanf(" %c", &op) == 1 && op != '#') {
        /* 读取下一个矩阵 */
        for (i = 0; i < n; i++) {
            for (j = 0; j < n; j++) {
                if (scanf("%d", &temp[i][j]) != 1) {
                    return 0;
                }
            }
        }

        /* 按运算符对结果矩阵进行更新 */
        if (op == '+') {
            for (i = 0; i < n; i++) {
                for (j = 0; j < n; j++) {
                    result[i][j] += temp[i][j];
                }
            }
        } else if (op == '-') {
            for (i = 0; i < n; i++) {
                for (j = 0; j < n; j++) {
                    result[i][j] -= temp[i][j];
                }
            }
        }
        /* 题目保证运算符只会是 +、- 或 #，因此无需额外处理非法字符 */
    }

    /* 按要求格式输出结果矩阵：每个元素宽度为5，右对齐 */
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            printf("%5d", result[i][j]);
        }
        printf("\n");
    }

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：`O(k * N^2)`，其中 `k` 为参与运算的矩阵个数，`N` 为矩阵阶数。每读取并处理一个矩阵都需要遍历 `N^2` 个元素。
- 空间复杂度：`O(N^2)`，使用了两个 `N x N` 的矩阵数组保存结果矩阵和临时矩阵。

