```c
#include <stdio.h>

int main(void)
{
    FILE *fin, *fout;
    int ch;
    int in_blank = 0;  // 标记当前是否处于连续空格/制表符区域

    /* 按题目要求打开文件 */
    fin = fopen("fcopy.in", "r");
    if (fin == NULL) {
        return 1;  // 输入文件打开失败
    }

    fout = fopen("fcopy.out", "w");
    if (fout == NULL) {
        fclose(fin);
        return 1;  // 输出文件打开失败
    }

    /* 逐字符读取并处理 */
    while ((ch = fgetc(fin)) != EOF) {
        if (ch == ' ' || ch == '\t') {
            /* 连续的空格或制表符，只输出一个空格 */
            if (!in_blank) {
                fputc(' ', fout);
                in_blank = 1;
            }
        } else {
            /* 其它字符保持不变 */
            fputc(ch, fout);
            in_blank = 0;
        }
    }

    fclose(fin);
    fclose(fout);

    return 0;
}
```

