**完整代码：**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LEN 1024
#define MAX_NUMS 20
#define MAX_RESULT 40

/* 降序排序比较函数 */
int cmp_desc(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return y - x;  /* 从大到小 */
}

/* 
 * 将一行字符串解析为整数数组
 * line: 输入的一整行
 * arr : 存放解析出的整数
 * 返回值：该行整数个数
 */
int parse_line(char *line, int arr[]) {
    int count = 0;
    char *token = strtok(line, " \t\r\n");

    while (token != NULL && count < MAX_NUMS) {
        arr[count++] = atoi(token);
        token = strtok(NULL, " \t\r\n");
    }

    return count;
}

/* 判断 value 是否在数组 arr[0..n-1] 中 */
int exists_in_array(int arr[], int n, int value) {
    int i;
    for (i = 0; i < n; i++) {
        if (arr[i] == value) {
            return 1;
        }
    }
    return 0;
}

int main(void) {
    char line1[MAX_LINE_LEN], line2[MAX_LINE_LEN];
    int a[MAX_NUMS], b[MAX_NUMS];
    int result[MAX_RESULT];
    int n1, n2, rn = 0;
    int i;

    /* 读取两行输入 */
    if (fgets(line1, sizeof(line1), stdin) == NULL) {
        return 0;
    }
    if (fgets(line2, sizeof(line2), stdin) == NULL) {
        return 0;
    }

    /* 解析两组整数 */
    n1 = parse_line(line1, a);
    n2 = parse_line(line2, b);

    /* 将只在第一组中出现的元素加入结果 */
    for (i = 0; i < n1; i++) {
        if (!exists_in_array(b, n2, a[i])) {
            result[rn++] = a[i];
        }
    }

    /* 将只在第二组中出现的元素加入结果 */
    for (i = 0; i < n2; i++) {
        if (!exists_in_array(a, n1, b[i])) {
            result[rn++] = b[i];
        }
    }

    /* 按从大到小排序 */
    qsort(result, rn, sizeof(int), cmp_desc);

    /* 按要求输出，元素之间以一个空格分隔 */
    for (i = 0; i < rn; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", result[i]);
    }

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：`O((n1 + n2)^2 + k log k)`，其中 `n1`、`n2` 分别为两组整数个数，`k` 为异或集元素个数。由于每行最多 20 个整数，实际开销很小。
- 空间复杂度：`O(n1 + n2 + k)`，用于存储两组输入和结果数组。

