#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double x;
    double y;
} Point;

int main(void) {
    int n;
    Point p[15];
    double area2 = 0.0;  // 面积的 2 倍（使用鞋带公式累计）

    /* 读取点的个数 */
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    /* 读取各顶点坐标 */
    for (int i = 0; i < n; i++) {
        if (scanf("%lf %lf", &p[i].x, &p[i].y) != 2) {
            return 0;
        }
    }

    /*
     * 使用鞋带公式计算多边形面积：
     * S = 1/2 * |sum(x_i*y_{i+1} - y_i*x_{i+1})|
     * 顶点按顺时针或逆时针给出都可以，最后取绝对值即可。
     */
    for (int i = 0; i < n; i++) {
        int next = (i + 1) % n;
        area2 += p[i].x * p[next].y - p[i].y * p[next].x;
    }

    if (area2 < 0) {
        area2 = -area2;
    }

    printf("%.2f\n", area2 / 2.0);

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：O(N)，只需遍历一遍所有顶点
- 空间复杂度：O(N)，用于存储顶点坐标（本题 N 最大仅为 15）

