#include <limits.h>

/*
 * 函数功能：
 * 将整数 n 转换为 b 进制字符串，结果存入 s 中。
 * 其中：
 *   2 <= b <= 36
 *   若 n 为负数，结果字符串以 '-' 开头
 *   数字 10~35 分别用 'a'~'z' 表示
 */
void itob(long long n, char s[], int b) {
    const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";
    char temp[100];
    int i = 0, j = 0;
    int is_negative = 0;
    unsigned long long value;

    /* 处理非法进制，保证函数尽量稳健 */
    if (b < 2 || b > 36) {
        s[0] = '\0';
        return;
    }

    /* 特殊情况：n == 0 */
    if (n == 0) {
        s[0] = '0';
        s[1] = '\0';
        return;
    }

    /* 记录符号，并安全地取绝对值 */
    if (n < 0) {
        is_negative = 1;
        /*
         * 不能直接写 value = -n;
         * 因为当 n 为最小负数时（如 INT_MIN / LLONG_MIN），直接取反可能溢出。
         * 用如下方式安全转换：
         */
        value = (unsigned long long)(-(n + 1)) + 1;
    } else {
        value = (unsigned long long)n;
    }

    /* 不断取余，得到低位到高位 */
    while (value > 0) {
        temp[i++] = digits[value % b];
        value /= b;
    }

    /* 若原数为负，最后补上负号 */
    if (is_negative) {
        temp[i++] = '-';
    }

    /* 逆序拷贝到 s 中 */
    while (i > 0) {
        s[j++] = temp[--i];
    }
    s[j] = '\0';
}

int main(void) {
    long long n;
    int b;
    char s[100];

    /* 读入整数 n 和进制 b */
    if (scanf("%lld %d", &n, &b) != 2) {
        return 0;
    }

    itob(n, s, b);

    /* 按题目要求输出结果字符串 */
    printf("%s", s);

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：O(log_b |n|)，每次循环将数除以 b，循环次数为数字的位数
- 空间复杂度：O(log_b |n|)，用于临时存储转换后的各位字符

