    if (scanf("%d", &x) != 1) {
        return 0;
    }

    /*
     * 设 x = a + (a+1) + ... + (a+n-1)
     * 则有：
     * x = n * (2a + n - 1) / 2
     * 即：
     * 2x = n * (2a + n - 1)
     *
     * 因为要求项数最多，所以从较大的 n 往较小的 n 枚举，
     * 找到的第一个可行解就是答案。
     *
     * 连续正整数至少 2 项，因此 n > 1
     * 又因为最小的 n 个连续正整数之和为 1+2+...+n = n(n+1)/2 <= x
     * 所以只需枚举满足 n(n+1)/2 <= x 的 n。
     */
    for (n = 2; n * (n + 1) / 2 <= x; n++) {
        /* 空循环，只是为了找到最大可能的 n */
    }
    n--;  // 回退到满足条件的最大 n

    for (; n >= 2; n--) {
        int numerator = x - n * (n - 1) / 2;
        /*
         * 由：
         * x = n*a + n(n-1)/2
         * 得：
         * a = (x - n(n-1)/2) / n
         *
         * 只要 numerator 能被 n 整除，且 a >= 1，则可构成合法分解。
