#include <stdio.h>

int main(void) {
    int n;

    /* 读入一个合数 */
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    /* 
       按从小到大的顺序分解质因数：
       先不断尝试用 2, 3, 4, ... 去除 n。
       每当 i 能整除 n，说明 i 是当前最小质因数，输出它，
       并将 n 除以 i，继续尝试同一个 i。
    */
    for (int i = 2; i <= n / i; i++) {
        while (n % i == 0) {
            printf("%d ", i);
            n /= i;
        }
    }

    /* 
       如果循环结束后 n > 1，说明剩余的 n 本身就是一个质数，
       也是分解结果中的最后一个质因数。
    */
    if (n > 1) {
        printf("%d", n);
    }

    return 0;
}
```

