```c
#include <stdio.h>
#include <math.h>

int main(void) {
    double e;

    /* 读取精度 e */
    if (scanf("%lf", &e) != 1) {
        return 0;
    }

    /* 
       按题意：
       π/2 = 1 + 1!/3 + 2!/(3×5) + 3!/(3×5×7) + ... + (n-1)!/(3×5×...×(2n-1))

       设第 k 项（从 k=0 开始）为：
       t_k = k! / (3×5×...×(2k+1))
       其中 t_0 = 1

       则有递推关系：
       t_k = t_(k-1) * k / (2k+1), k>=1

       记：
       pi_n 表示取前 n 项时计算得到的 π 值
       即 pi_n = 2 * (t_0 + t_1 + ... + t_(n-1))

       需要找到最小 n(n>=2)，使得：
       |pi_n - pi_(n-1)| < e
    */

    int n = 1;              /* 当前已经计算了 1 项：t_0 */
    double term = 1.0;      /* t_0 */
    double sum = 1.0;       /* 前 1 项和 */
    double pi_prev = 2.0;   /* pi_1 */

    while (1) {
        /* 计算下一项：t_(n) ，此时将从 n=1 开始依次生成 t_1, t_2, ... */
        term = term * n / (2.0 * n + 1.0);
        sum += term;
        n++;  /* 现在已经有 n 项，当前 π 为 pi_n */

        double pi_now = 2.0 * sum;

        /* 至少迭代两次，即 n>=2；并判断相邻两次 π 的差是否小于 e */
        if (n >= 2 && fabs(pi_now - pi_prev) < e) {
            printf("%d %.7f\n", n, pi_now);
            break;
        }

        pi_prev = pi_now;
    }

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：O(n)，其中 n 为满足精度要求时的最小迭代次数
- 空间复杂度：O(1)

