#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 256
#define MAX_PART 256

/* 
 * 将字符串 s 中的内容按“单词间只保留一个空格”的规则规范化到 out 中。
 * 单词定义：由除空格和水平制表符之外的其它字符构成。
 * 例如：
 *   "  Tom\t  Hanks  " -> "Tom Hanks"
 */
void normalize_spaces(const char *s, char *out) {
    int i = 0, j = 0;
    int first_word = 1;

    while (s[i] != '\0') {
        /* 跳过空格和制表符 */
        while (s[i] == ' ' || s[i] == '\t') {
            i++;
        }

        /* 如果已经到字符串末尾，结束 */
        if (s[i] == '\0') {
            break;
        }

        /* 不是第一个单词时，先补一个空格 */
        if (!first_word) {
            out[j++] = ' ';
        }

        /* 复制当前单词 */
        while (s[i] != '\0' && s[i] != ' ' && s[i] != '\t') {
            out[j++] = s[i++];
        }

        first_word = 0;
    }

    out[j] = '\0';
}

int main(void) {
    int pos;
    char line[MAX_LINE];

    /* 读取冒号固定位置 */
    if (scanf("%d", &pos) != 1) {
        return 0;
    }

    /* 吃掉整数后这一行剩余内容（主要是换行） */
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF) {
        ;
    }

    /* 逐行读取直到 EOF */
    while (fgets(line, sizeof(line), stdin) != NULL) {
        char left_raw[MAX_PART] = {0};
        char right_raw[MAX_PART] = {0};
        char left[MAX_PART] = {0};
        char right[MAX_PART] = {0};
        char *colon;
        int left_len, spaces_before;

        /* 去掉行末换行符 */
        line[strcspn(line, "\r\n")] = '\0';

        /* 查找冒号 */
        colon = strchr(line, ':');
        if (colon == NULL) {
            /* 按题意正常情况下每行都有冒号，这里做稳健处理：无冒号则跳过 */
            continue;
        }

        /* 分离冒号左右两部分 */
        {
            int l_len = (int)(colon - line);
            strncpy(left_raw, line, l_len);
            left_raw[l_len] = '\0';
            strcpy(right_raw, colon + 1);
        }

        /* 规范化左右两边的空白 */
        normalize_spaces(left_raw, left);
        normalize_spaces(right_raw, right);

        left_len = (int)strlen(left);

        /*
         * 冒号位置从 1 开始计数。
         * 输出格式要求为：
         *   [若干空格][左串] : [右串]
         * 因此冒号前共有：
         *   前导空格 + 左串长度 + 1个空格
         * 应满足：冒号位于第 pos 列
         * 即：前导空格 = pos - 1 - (左串长度 + 1) = pos - left_len - 2
         *
         * 题目保证输入整数足够大，这里仍做保护处理，避免负数。
         */
        spaces_before = pos - left_len - 2;
        if (spaces_before < 0) {
            spaces_before = 0;
        }

        /* 输出前导空格 */
        for (int i = 0; i < spaces_before; i++) {
            putchar(' ');
        }

        /* 按规则输出本行 */
        if (left_len > 0) {
            printf("%s : ", left);
        } else {
            /* 左边没有单词时，冒号左边仍保留一个空格 */
            printf(" : ");
        }

        if (right[0] != '\0') {
            printf("%s", right);
        }

        putchar('\n');
    }

    return 0;
}
