**完整代码：**
```c
#include <stdio.h>

int main(void) {
    FILE *fp;
    int ch, next;
    long long totalChars = 0;    /* 文件总字符数 */
    long long commentChars = 0;  /* 注释内部字符数，不含 /* 和 *\/ */
    int inComment = 0;           /* 是否处于注释内部 */

    fp = fopen("filein.c", "r");
    if (fp == NULL) {
        /* 若文件打不开，程序直接结束 */
        return 0;
    }

    while ((ch = fgetc(fp)) != EOF) {
        totalChars++;  /* 文件中的每个字符都计入总字符数 */

        if (!inComment) {
            /* 不在注释中时，检查是否遇到注释开始符号 "/*" */
            if (ch == '/') {
                next = fgetc(fp);
                if (next != EOF) {
                    totalChars++;  /* 预读的字符同样属于文件总字符数 */

                    if (next == '*') {
                        /* 进入注释状态，"/*" 本身不计入注释字符数 */
                        inComment = 1;
                    } else {
                        /* 不是注释开始，继续从 next 之后处理 */
                        ungetc(next, fp);
                        totalChars--; /* ungetc 后，该字符后续还会再次读取，因此此处撤销一次统计 */
                    }
                }
            }
        } else {
            /* 在注释中时，检查是否遇到注释结束符号 "*\/" */
            if (ch == '*') {
                next = fgetc(fp);
                if (next != EOF) {
                    totalChars++;  /* 预读字符也属于文件总字符数 */

                    if (next == '/') {
                        /* 注释结束，"*\/" 不计入注释字符数 */
                        inComment = 0;
                    } else {
                        /* 当前 ch='*' 只是普通注释内容字符 */
                        commentChars++;
                        ungetc(next, fp);
                        totalChars--; /* 该字符稍后会重新读取，撤销本次统计 */
                    }
                } else {
                    /* 文件在注释中以 '*' 结束，'*' 作为注释内容计入 */
                    commentChars++;
                }
            } else {
                /* 注释中的普通字符 */
                commentChars++;
            }
        }
    }

    fclose(fp);

    /* 按要求：直接截掉小数部分，不四舍五入 */
    if (totalChars == 0) {
        printf("0%%");
    } else {
        printf("%lld%%", (commentChars * 100) / totalChars);
    }

    return 0;
}
