```c
#include <stdio.h>
#include <string.h>

#define MAX_LEN 1000

/* 去掉 fgets 读入字符串末尾的换行符 */
void remove_newline(char *s) {
    int len = strlen(s);
    if (len > 0 && s[len - 1] == '\n') {
        s[len - 1] = '\0';
    }
}

int main(void) {
    char str[MAX_LEN + 1];
    char sub[MAX_LEN + 1];
    char result[MAX_LEN + 1];
    int i = 0, j = 0;
    int len_str, len_sub;

    /* 读取原字符串 */
    if (fgets(str, sizeof(str), stdin) == NULL) {
        return 0;
    }

    /* 读取子串 */
    if (fgets(sub, sizeof(sub), stdin) == NULL) {
        return 0;
    }

    /* 去掉换行符 */
    remove_newline(str);
    remove_newline(sub);

    len_str = strlen(str);
    len_sub = strlen(sub);

    /* 如果子串为空，则直接输出原字符串 */
    if (len_sub == 0) {
        printf("%s\n", str);
        return 0;
    }

    /* 从左到右扫描，删除所有出现的子串 */
    while (i < len_str) {
        if (i <= len_str - len_sub && strncmp(&str[i], sub, len_sub) == 0) {
            /* 匹配到子串，跳过这段 */
            i += len_sub;
        } else {
            /* 不匹配则保留当前字符 */
            result[j++] = str[i++];
        }
    }

    result[j] = '\0';

    /* 输出删除后的字符串 */
    printf("%s\n", result);

    return 0;
}
```

