#include <stdio.h>

int main(void) {
    int count[26] = {0};
    int ch;
    int i, level;
    int maxCount = 0;

    /* 读取直到文件结束（EOF） */
    while ((ch = getchar()) != EOF) {
        /* 只统计小写字母 */
        if (ch >= 'a' && ch <= 'z') {
            count[ch - 'a']++;
        }
    }

    /* 找到出现次数最多的字母，用于确定柱状图高度 */
    for (i = 0; i < 26; i++) {
        if (count[i] > maxCount) {
            maxCount = count[i];
        }
    }

    /* 从最高层到最低层逐行输出柱状图 */
    for (level = maxCount; level >= 1; level--) {
        for (i = 0; i < 26; i++) {
            if (count[i] >= level) {
                putchar('*');
            } else {
                putchar(' ');
            }
        }
        putchar('\n');
    }

    /* 输出最后一行字母标识 */
    for (i = 0; i < 26; i++) {
        putchar('a' + i);
    }
    putchar('\n');

    return 0;
}
