#include <stdio.h>
#include <string.h>

#define MAXN 1005

/* 判断字符是否为小写字母 */
int is_lower(char c) {
    return c >= 'a' && c <= 'z';
}

/* 判断字符是否为大写字母 */
int is_upper(char c) {
    return c >= 'A' && c <= 'Z';
}

/* 判断字符是否为数字 */
int is_digit_char(char c) {
    return c >= '0' && c <= '9';
}

/* 判断扩展符两侧字符是否属于同一合法范围，并且右侧字符大于左侧字符 */
int can_expand(char left, char right) {
    if (is_lower(left) && is_lower(right) && right > left) return 1;
    if (is_upper(left) && is_upper(right) && right > left) return 1;
    if (is_digit_char(left) && is_digit_char(right) && right > left) return 1;
    return 0;
}

int main() {
    char s[MAXN];
    int len, i, ch;

    /* 读取一整行输入 */
    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }

    /* 去掉行末换行符 */
    len = strlen(s);
    if (len > 0 && s[len - 1] == '\n') {
        s[len - 1] = '\0';
        len--;
    }

    for (i = 0; i < len; i++) {
        /* 只有中间位置的 '-' 才有可能作为扩展符 */
        if (s[i] == '-' && i > 0 && i < len - 1 && can_expand(s[i - 1], s[i + 1])) {
            /* 输出 left 和 right 之间缺少的字符，不输出 '-' 本身 */
            for (ch = s[i - 1] + 1; ch < s[i + 1]; ch++) {
                putchar(ch);
            }
        } else {
            /* 其它情况原样输出 */
            putchar(s[i]);
        }
    }

    return 0;
}
