## 标准答案

**完整代码：**
```c
#include <stdio.h>
#include <ctype.h>

/*
 * 题意：
 * 计算一个只含 +、-、*、/ 的整数表达式，表达式以 '=' 结束，可能含空格。
 * 不含括号，且保证表达式合法。
 *
 * 思路：
 * 利用“先乘除，后加减”的规则：
 * 1. result 用来累计已经确定的加减结果；
 * 2. term   用来保存当前这一段乘除链的结果；
 * 3. op     表示“当前读到的数字”应如何作用到 term 上（* / 或初始赋值）；
 * 4. add_op 表示当前 term 之后应以 + 还是 - 加入 result。
 *
 * 例如：5 - 1 * 2 * 3 + 12 / 2 / 2 =
 * - 先得到第一段 term=5，遇到 '-'，result += 5
 * - 再计算乘除链 1*2*3=6，遇到 '+'，result -= 6
 * - 再计算乘除链 12/2/2=3，遇到 '='，result += 3
 * 最终 result=2
 */

int main(void) {
    long long num;         /* 当前读到的整数 */
    long long term = 0;    /* 当前乘除链的值 */
    long long result = 0;  /* 最终结果 */

    char ch;
    char op = 0;           /* 作用于当前数字与 term 的运算符：'*' '/' 或 0(表示初始化) */
    char add_op = '+';     /* 当前 term 加入 result 时使用的运算符：'+' 或 '-' */

    int has_number = 0;    /* 是否已经成功读入过至少一个数字 */

    while ((ch = getchar()) != EOF) {
        if (isspace((unsigned char)ch)) {
            continue;  /* 忽略空格、换行等空白字符 */
        }

        if (isdigit((unsigned char)ch)) {
            /* 读入一个完整整数 */
            num = ch - '0';
            while ((ch = getchar()) != EOF && isdigit((unsigned char)ch)) {
                num = num * 10 + (ch - '0');
            }

            has_number = 1;

            /* 将该数字并入当前乘除链 */
            if (op == 0) {
                term = num;          /* 这是当前链的第一个数 */
            } else if (op == '*') {
                term = term * num;
            } else if (op == '/') {
                term = term / num;   /* 题目要求整数除法 */
            }

            /* 如果当前 ch 不是 EOF，则它是数字后的第一个非数字字符，继续下面处理 */
        }

        /* 处理运算符或结束符 */
        if (ch == '+' || ch == '-' || ch == '=' || ch == '*' || ch == '/') {
            if (ch == '*' || ch == '/') {
                /* 继续当前乘除链 */
                op = ch;
            } else {
                /* 遇到 +、-、=，说明当前乘除链结束，应并入 result */
                if (has_number) {
                    if (add_op == '+') {
                        result += term;
                    } else {
                        result -= term;
                    }
                }

                if (ch == '+' || ch == '-') {
                    add_op = ch; /* 下一段乘除链并入 result 时使用 */
                    op = 0;      /* 新一段乘除链开始 */
                } else if (ch == '=') {
                    /* 表达式结束，输出结果 */
                    printf("%lld\n", result);
                    return 0;
                }
            }
        }
    }

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：O(n)，其中 n 为输入表达式的长度。每个字符最多被读取和处理常数次。
- 空间复杂度：O(1)，只使用了若干辅助变量，没有使用与输入规模相关的额外空间。

