    int exponent;

    /* 读取输入的一整行 */
    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }

    /* 去掉末尾换行符 */
    len = (int)strlen(s);
    if (len > 0 && s[len - 1] == '\n') {
        s[len - 1] = '\0';
        len--;
    }

    /* 找到小数点位置 */
    for (i = 0; i < len; i++) {
        if (s[i] == '.') {
            dot = i;
            break;
        }
    }

    /* 找到第一个非0数字（跳过小数点） */
    for (i = 0; i < len; i++) {
        if (s[i] != '.' && s[i] != '0') {
            first_nonzero = i;
            break;
        }
    }

    /*
     * 按题意输入数据全为有效数据，且小数点前后必有数字，
     * 实际上不会出现全为0的情况。这里做一个稳健性保护。
     */
    if (first_nonzero == -1 || dot == -1) {
        return 0;
    }

    /*
     * 计算指数：
     * 若首个非0数字在小数点左边，指数 = 小数点位置 - 该数字位置 - 1
     * 若首个非0数字在小数点右边，指数 = -(该数字位置 - 小数点位置)
     */
    if (first_nonzero < dot) {
        exponent = dot - first_nonzero - 1;
    } else {
        exponent = -(first_nonzero - dot);
    }

    /*
     * 输出底数部分：
     * 取从第一个非0数字开始的所有数字（忽略原小数点），
     * 第一位作为小数点前数字，后续若存在则作为小数部分。
     */
    putchar(s[first_nonzero]);

    /* 判断后面是否还有数字可输出 */
    int has_more = 0;
    for (i = first_nonzero + 1; i < len; i++) {
        if (s[i] != '.') {
            has_more = 1;
            break;
        }
    }

    if (has_more) {
        putchar('.');
        for (j = first_nonzero + 1; j < len; j++) {
            if (s[j] != '.') {
                putchar(s[j]);
            }
        }
    }

    /* 输出指数部分 */
    printf("e%d", exponent);

    return 0;
}
