**完整代码：**
```c
#include <stdio.h>
#include <string.h>

#define MAXN 105  /* 题目最长80位，这里开大一些更稳妥 */

/* 去掉字符串前导0，返回处理后起始位置的下标 */
int skip_leading_zeros(const char *s) {
    int i = 0;
    while (s[i] == '0' && s[i + 1] != '\0') {
        i++;
    }
    return i;
}

/* 比较两个非负整数字符串（已传入去掉前导0后的起始地址）
   返回值：
   1  -> a > b
   0  -> a == b
  -1  -> a < b
*/
int compare_num_str(const char *a, const char *b) {
    int len_a = (int)strlen(a);
    int len_b = (int)strlen(b);

    if (len_a > len_b) return 1;
    if (len_a < len_b) return -1;

    int cmp = strcmp(a, b);
    if (cmp > 0) return 1;
    if (cmp < 0) return -1;
    return 0;
}

/* 计算大整数减法：big - small，要求 big >= small
   结果存入 result（正常顺序字符串，且无多余前导0，若结果为0则为"0"）
*/
void subtract_num_str(const char *big, const char *small, char *result) {
    int len_big = (int)strlen(big);
    int len_small = (int)strlen(small);

    int i = len_big - 1;
    int j = len_small - 1;
    int k = 0;
    int borrow = 0;

    char temp[MAXN] = {0};  /* 先逆序保存结果 */

    while (i >= 0 || j >= 0) {
        int x = (i >= 0) ? (big[i] - '0') : 0;
        int y = (j >= 0) ? (small[j] - '0') : 0;

        x -= borrow;
        if (x < y) {
            x += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }

        temp[k++] = (char)(x - y + '0');
        i--;
        j--;
    }

    /* 去掉逆序结果末尾多余的0（即正序结果前导0） */
    while (k > 1 && temp[k - 1] == '0') {
        k--;
    }

    /* 逆序拷贝成正常顺序 */
    for (i = 0; i < k; i++) {
        result[i] = temp[k - 1 - i];
    }
    result[k] = '\0';
}

int main(void) {
    char A[MAXN], B[MAXN];
    char result[MAXN];

    /* 读入两个超长正整数，保留可能存在的前导0 */
    if (scanf("%104s", A) != 1) return 0;
    if (scanf("%104s", B) != 1) return 0;

    /* 找到去掉前导0后的有效部分 */
    char *a = A + skip_leading_zeros(A);
    char *b = B + skip_leading_zeros(B);

    int cmp = compare_num_str(a, b);

    if (cmp == 0) {
        /* 结果为0时只输出一个0 */
        printf("0\n");
    } else if (cmp > 0) {
        /* A > B，输出正数结果 */
        subtract_num_str(a, b, result);
        printf("%s\n", result);
    } else {
        /* A < B，输出负数结果 */
        subtract_num_str(b, a, result);
        printf("-%s\n", result);
    }

    return 0;
}
