int used[MAXN + 1];   // 标记某个数字是否已经使用

/* 输出当前排列 */
void printPermutation() {
    int i;
    for (i = 1; i <= n; i++) {
        if (i > 1) {
            printf(" ");
        }
        printf("%d", perm[i]);
    }
    printf("\n");
}

/* 
 * 深度优先搜索生成全排列
 * pos 表示当前要填写的位置（1~n）
 * 按 1~n 的顺序尝试数字，可保证输出满足“小数优先”原则
 */
void dfs(int pos) {
    int i;

    if (pos > n) {
        printPermutation();
        return;
    }

    for (i = 1; i <= n; i++) {
        if (!used[i]) {
            used[i] = 1;
            perm[pos] = i;

            dfs(pos + 1);

            used[i] = 0;  // 回溯
        }
    }
}

int main() {
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    dfs(1);

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：`O(N × N!)`  
  共有 `N!` 个排列，每个排列输出需要 `O(N)` 时间。
- 空间复杂度：`O(N)`  
  主要用于保存当前排列和访问标记，以及递归调用栈。

