/* 去掉字符串末尾的换行符 */
void remove_newline(char *s) {
    size_t len;
    if (s == NULL) return;
    len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) {
        s[len - 1] = '\0';
        len--;
    }
}

/* 判断 text 从当前位置开始的 len 个字符，是否与 pattern 大小写无关地相等 */
int match_ignore_case(const char *text, const char *pattern, size_t len) {
    size_t i;
    for (i = 0; i < len; i++) {
        if (tolower((unsigned char)text[i]) != tolower((unsigned char)pattern[i])) {
            return 0;
        }
    }
    return 1;
}

