    remove_newline(newStr);

    /* 打开输入文件 */
    fin = fopen(INPUT_FILE, "rb");
    if (fin == NULL) {
        return 0;
    }

    /* 读取整个文件内容到动态内存中 */
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), fin)) > 0) {
        if (size + bytesRead + 1 > capacity) {
            size_t newCapacity = (capacity == 0) ? (size + bytesRead + 1) : capacity;
            char *temp;

            while (newCapacity < size + bytesRead + 1) {
                newCapacity *= 2;
                if (newCapacity == 0) {
                    newCapacity = size + bytesRead + 1;
                    break;
                }
            }

            if (capacity == 0) {
                newCapacity = size + bytesRead + 1;
                if (newCapacity < 8192) {
                    newCapacity = 8192;
                }
            }

            temp = (char *)realloc(content, newCapacity);
            if (temp == NULL) {
                free(content);
                fclose(fin);
                return 0;
            }
            content = temp;
            capacity = newCapacity;
        }

        memcpy(content + size, buffer, bytesRead);
        size += bytesRead;
    }
    fclose(fin);

    if (content == NULL) {
        /* 空文件也要生成输出文件 */
        fout = fopen(OUTPUT_FILE, "wb");
        if (fout != NULL) {
            fclose(fout);
        }
        return 0;
    }
    content[size] = '\0';

    /* 打开输出文件 */
    fout = fopen(OUTPUT_FILE, "wb");
    if (fout == NULL) {
        free(content);
        return 0;
    }

    /* 若被替换字符串为空，为避免死循环，直接原样输出 */
    if (oldStr[0] == '\0') {
        fwrite(content, 1, size, fout);
        fclose(fout);
        free(content);
        return 0;
    }

    /* 顺序扫描并替换，大小写无关 */
    {
        size_t i = 0;
        size_t oldLen = strlen(oldStr);
        size_t newLen = strlen(newStr);

        while (i < size) {
            if (i + oldLen <= size && match_ignore_case(content + i, oldStr, oldLen)) {
                /* 匹配成功，输出替换串 */
                if (newLen > 0) {
                    fwrite(newStr, 1, newLen, fout);
                }
                i += oldLen;
            } else {
                /* 不匹配，原字符输出 */
                fputc((unsigned char)content[i], fout);
                i++;
            }
        }
    }

    fclose(fout);
    free(content);
    return 0;
}
