## 标准答案

**完整代码：**
```c
#include <stdio.h>
#include <string.h>

#define MAX_KEY_LEN 55

int main(void) {
    char key[MAX_KEY_LEN];
    char mapping[26];          /* 原字母 a~z 对应的加密字母 */
    int used[26] = {0};        /* 标记某字母是否已经加入映射表 */
    int idx = 0;
    int i, ch;
    FILE *fin, *fout;

    /* 读入密钥串 */
    if (scanf("%54s", key) != 1) {
        return 0;
    }

    /* 1. 先把密钥中不重复的字母按出现顺序加入映射表 */
    for (i = 0; key[i] != '\0'; i++) {
        if (key[i] >= 'a' && key[i] <= 'z') {
            int t = key[i] - 'a';
            if (!used[t]) {
                used[t] = 1;
                mapping[idx++] = key[i];
            }
        }
    }

    /* 2. 再将其余未出现的字母按反序 z~a 追加到映射表 */
    for (i = 25; i >= 0; i--) {
        if (!used[i]) {
            mapping[idx++] = (char)('a' + i);
        }
    }

    /* 打开输入文件 encrypt.txt */
    fin = fopen("encrypt.txt", "r");
    if (fin == NULL) {
        return 0;
    }

    /* 打开输出文件 output.txt */
    fout = fopen("output.txt", "w");
    if (fout == NULL) {
        fclose(fin);
        return 0;
    }

    /* 逐字符读取并加密写入 */
    while ((ch = fgetc(fin)) != EOF) {
        if (ch >= 'a' && ch <= 'z') {
            fputc(mapping[ch - 'a'], fout);
        } else {
            /* 非小写字母字符不加密，原样输出 */
            fputc(ch, fout);
        }
    }

    fclose(fin);
    fclose(fout);

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：O(n)，其中 n 为文件 `encrypt.txt` 的字符数。构造映射表只需 O(1)（最多处理 26 个字母和长度不超过 50 的密钥）。
- 空间复杂度：O(1)，只使用了固定大小的数组。

