```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_N 100
#define MAX_NAME 21
#define MAX_PHONE 12
#define MAX_FINAL_NAME 32

/* 通讯录项结构体 */
typedef struct {
    char name[MAX_FINAL_NAME];   // 整理后姓名（可能带 _1、_2 ...）
    char phone[MAX_PHONE];       // 手机号（11位数字字符 + '\0'）
    char baseName[MAX_NAME];     // 原始姓名
} Contact;

/* 按姓名升序排序使用的比较函数 */
int cmpContact(const void *a, const void *b) {
    const Contact *x = (const Contact *)a;
    const Contact *y = (const Contact *)b;
    return strcmp(x->name, y->name);
}

int main(void) {
    int n;
    Contact contacts[MAX_N];     // 最终保留并整理后的通讯录
    int keptCount = 0;           // 当前保留的条目数

    /* 记录每个原始姓名已经出现了多少次（仅统计保留下来的非完全重复项） */
    char nameList[MAX_N][MAX_NAME];
    int nameCount[MAX_N];
    int distinctNameNum = 0;

    if (scanf("%d", &n) != 1) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        char inputName[MAX_NAME];
        char inputPhone[MAX_PHONE];
        int isExactDuplicate = 0;

        if (scanf("%20s %11s", inputName, inputPhone) != 2) {
            return 0;
        }

        /* 先判断是否为“姓名和电话都相同”的完全重复项 */
        for (int j = 0; j < keptCount; j++) {
            if (strcmp(contacts[j].baseName, inputName) == 0 &&
                strcmp(contacts[j].phone, inputPhone) == 0) {
                isExactDuplicate = 1;
                break;
            }
        }

        /* 完全重复项直接丢弃 */
        if (isExactDuplicate) {
            continue;
        }

        /* 查找该原始姓名此前已经保留了多少次 */
        int pos = -1;
        for (int j = 0; j < distinctNameNum; j++) {
            if (strcmp(nameList[j], inputName) == 0) {
                pos = j;
                break;
            }
        }

        /* 新姓名：第一次出现，原样保留 */
        if (pos == -1) {
            strcpy(nameList[distinctNameNum], inputName);
            nameCount[distinctNameNum] = 1;

            strcpy(contacts[keptCount].baseName, inputName);
            strcpy(contacts[keptCount].name, inputName);
            strcpy(contacts[keptCount].phone, inputPhone);

            distinctNameNum++;
            keptCount++;
        } else {
            /* 同名但电话不同：加 _1、_2、_3 ... */
            strcpy(contacts[keptCount].baseName, inputName);
            snprintf(contacts[keptCount].name, MAX_FINAL_NAME, "%s_%d", inputName, nameCount[pos]);
            strcpy(contacts[keptCount].phone, inputPhone);

            nameCount[pos]++;
            keptCount++;
        }
    }

    /* 按整理后的姓名排序 */
    qsort(contacts, keptCount, sizeof(Contact), cmpContact);

    /* 输出结果 */
    for (int i = 0; i < keptCount; i++) {
        printf("%s %s\n", contacts[i].name, contacts[i].phone);
    }

    return 0;
}
```

