**完整代码：**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BOOKS 500
#define TITLE_LEN 51
#define AUTHOR_LEN 21
#define PRESS_LEN 31
#define DATE_LEN 11

typedef struct {
    char title[TITLE_LEN];
    char author[AUTHOR_LEN];
    char press[PRESS_LEN];
    char date[DATE_LEN];
} Book;

/* 按书名字典序比较 */
int cmpBook(const void *a, const void *b) {
    const Book *pa = (const Book *)a;
    const Book *pb = (const Book *)b;
    return strcmp(pa->title, pb->title);
}

/* 按题目要求格式输出一本书信息 */
void printBook(FILE *fp, const Book *b) {
    fprintf(fp, "%-50s %-20s %-30s %-10s\n",
            b->title, b->author, b->press, b->date);
}

/* 从 books.txt 读入原始书库 */
int loadBooks(Book books[]) {
    FILE *fp = fopen("books.txt", "r");
    int count = 0;

    if (fp == NULL) {
        /* 若文件不存在，则视为空书库 */
        return 0;
    }

    while (count < MAX_BOOKS &&
           fscanf(fp, "%50s %20s %30s %10s",
                  books[count].title,
                  books[count].author,
                  books[count].press,
                  books[count].date) == 4) {
        count++;
    }

    fclose(fp);
    return count;
}

/* 将当前有序书库保存到 ordered.txt */
void saveBooks(Book books[], int count) {
    FILE *fp = fopen("ordered.txt", "w");
    int i;

    if (fp == NULL) {
        return;
    }

    for (i = 0; i < count; i++) {
        printBook(fp, &books[i]);
    }

    fclose(fp);
}

/* 向有序数组中插入一本书，保持有序 */
void insertBook(Book books[], int *count, Book newBook) {
    int pos = 0, i;

    if (*count >= MAX_BOOKS) {
        return;
    }

    /* 找到插入位置：第一个书名大于新书名的位置 */
    while (pos < *count && strcmp(books[pos].title, newBook.title) < 0) {
        pos++;
    }

    /* 元素后移 */
    for (i = *count; i > pos; i--) {
        books[i] = books[i - 1];
    }

    books[pos] = newBook;
    (*count)++;
}

/* 查找标题中包含关键字的图书，并按当前有序顺序输出 */
void searchBooks(Book books[], int count, const char *keyword) {
    int i;
    for (i = 0; i < count; i++) {
        if (strstr(books[i].title, keyword) != NULL) {
            printBook(stdout, &books[i]);
        }
    }
}

/* 删除标题中包含关键字的所有图书 */
void deleteBooks(Book books[], int *count, const char *keyword) {
    int i, j = 0;
    for (i = 0; i < *count; i++) {
        if (strstr(books[i].title, keyword) == NULL) {
            books[j++] = books[i];
        }
    }
    *count = j;
}

int main(void) {
    Book books[MAX_BOOKS];
    int count, op;

    /* 读入原始书库并排序 */
    count = loadBooks(books);
    qsort(books, count, sizeof(Book), cmpBook);

    /* 循环处理用户操作 */
    while (scanf("%d", &op) == 1) {
        if (op == 0) {
            saveBooks(books, count);
            break;
        } else if (op == 1) {
            /* 录入一本新书 */
            Book newBook;
            if (scanf("%50s %20s %30s %10s",
                      newBook.title,
                      newBook.author,
                      newBook.press,
                      newBook.date) == 4) {
                insertBook(books, &count, newBook);
            }
        } else if (op == 2) {
            /* 查找 */
            char keyword[TITLE_LEN];
            if (scanf("%50s", keyword) == 1) {
                searchBooks(books, count, keyword);
            }
        } else if (op == 3) {
            /* 删除 */
            char keyword[TITLE_LEN];
            if (scanf("%50s", keyword) == 1) {
                deleteBooks(books, &count, keyword);
            }
        }
    }

    return 0;
}
```

**复杂度分析：**
- 时间复杂度：  
  - 初始排序为 `O(n log n)`  
  - 单次录入最坏为 `O(n)`  
  - 单次查找为 `O(n * k)`，其中 `k` 为子串匹配的平均比较代价，可视为书名长度上界内的常数  
  - 单次删除为 `O(n * k)`  
- 空间复杂度：`O(n)`，用于存储图书信息数组，其中 `n <= 500`

